><option value="pending">Pendiente</option><option value="expired">Vencida</option><option value="revoked">Revocada</option></select></div><div class="col-md-4"><label class="form-label">Vigencia hasta</label><input class="form-control" type="datetime-local" name="ends_at" id="membershipEnds"></div><div class="col-12 d-flex flex-wrap gap-3"><label class="form-check"><input class="form-check-input" type="checkbox" name="is_primary" id="membershipPrimary"><span class="form-check-label">Principal</span></label><label class="form-check"><input class="form-check-input" type="checkbox" name="can_invite" id="membershipInvite"><span class="form-check-label">Invitar</span></label><label class="form-check"><input class="form-check-input" type="checkbox" name="can_reserve" id="membershipReserve"><span class="form-check-label">Reservar</span></label><span class="text-body-secondary">Las cámaras y accesos exactos se administran con el botón <i class="bi bi-shield-check"></i> de esta relación.</span></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar vinculación</button></div></form></div></div></div>
<div class="modal fade" id="residentAccountModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form method="post" action="<?=url('resident-account-save')?>"><?=csrf_field()?><input type="hidden" name="person_id" id="residentAccountPerson"><div class="modal-header"><div><h5 class="modal-title">Acceso a Property App</h5><small class="text-body-secondary" id="residentAccountName"></small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-3"><label class="form-label">Correo de acceso</label><input class="form-control" type="email" name="email" id="residentAccountEmail"></div><div class="mb-3"><label class="form-label">Nombre de usuario opcional</label><input class="form-control" name="username" id="residentAccountUsername"></div><div class="mb-3"><label class="form-label">Contraseña <?=e('inicial o nueva')?></label><input class="form-control" type="password" name="password" minlength="8" id="residentAccountPassword" autocomplete="new-password"><small class="text-body-secondary">Al editar, déjala vacía para conservar la contraseña actual.</small></div><div class="mb-3"><label class="form-label">Estado</label><select class="form-select" name="status" id="residentAccountStatus"><option value="active">Activo</option><option value="pending">Pendiente</option><option value="blocked">Bloqueado</option><option value="revoked">Revocado</option></select></div><div class="alert alert-info mb-0">Al iniciar sesión desde el teléfono, esta persona verá únicamente las unidades y permisos registrados en sus vinculaciones.</div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary"><i class="bi bi-phone"></i> Guardar acceso</button></div></form></div></div></div>
<form method="post" action="<?=url('membership-delete')?>" id="personMembershipDeleteForm" class="d-none"><?=csrf_field()?><input type="hidden" name="id" id="personMembershipDeleteId"></form>
<script>
const zkPersonMap=<?=json_encode(array_reduce($zkPersonMappings,static function(array $c,array $r):array{$c[(int)$r['id']]=$r;return $c;},[]),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const personMemberships=<?=json_encode($membershipsByPerson,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const membershipPermissionBase=<?=json_encode(url('membership-permissions'))?>;document.addEventListener('DOMContentLoaded',()=>{const accountModal=document.getElementById('residentAccountModal');if(accountModal)accountModal.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;let a={};try{a=JSON.parse(b?.dataset.account||'{}')}catch(x){}document.getElementById('residentAccountPerson').value=b?.dataset.person||'';document.getElementById('residentAccountName').textContent=b?.dataset.name||'';document.getElementById('residentAccountEmail').value=a.email||b?.dataset.email||'';document.getElementById('residentAccountUsername').value=a.username||'';document.getElementById('residentAccountPassword').value='';document.getElementById('residentAccountStatus').value=a.status||'active';});const person=document.getElementById('personModal');person.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;let d={};if(b&&b.classList.contains('js-edit-person')){try{d=JSON.parse(b.dataset.json||'{}')}catch(x){d={}}}document.getElementById('personModalTitle').textContent=d.id?'Editar persona':'Nueva persona';const map={personId:'id',personFirst:'first_name',personLast:'last_name',personDisplay:'display_name',personDocType:'document_type',personDoc:'document_number',personPhone:'phone',personEmail:'email',personStatus:'status'};for(const [el,k] of Object.entries(map)){document.getElementById(el).value=d[k]??(el==='personStatus'?'active':'');}document.getElementById('personProperty').value='';const pap=document.getElementById('personAccessProfile');if(pap)pap.value='';const z=zkPersonMap[d.id]||{};const zpin=document.getElementById('personZkPin');if(zpin)zpin.value=z.zk_pin||'';const zcb=document.getElementById('personProvisionZk');if(zcb)zcb.checked=false;const zd=document.getElementById('personZkDept');if(zd)zd.value='';const zl=document.getElementById('personZkLevels');if(zl)Array.from(zl.options).forEach(o=>o.selected=false);const relSection=document.getElementById('personExistingMembershipsSection'),relList=document.getElementById('personExistingMemberships');if(relSection&&relList){const rows=d.id?(personMemberships[d.id]||[]):[];relSection.classList.toggle('d-none',!d.id);relList.innerHTML=rows.length?rows.map(r=>`<div class="person-membership-card"><div class="d-flex justify-content-between gap-2"><div><strong>${escapeHtml(r.property_name||r.property_code||'Unidad')}</strong><div class="meta">${escapeHtml(r.relationship_type||'')} · Perfil: ${escapeHtml(r.access_profile_name||'Automático')}</div></div><span class="badge text-bg-light border align-self-start">${escapeHtml(r.status||'active')}</span></div><div class="actions"><a class="btn btn-sm btn-outline-success" href="${membershipPermissionBase}&id=${encodeURIComponent(r.id)}"><i class="bi bi-shield-check"></i> Perfil y permisos efectivos</a><button type="button" class="btn btn-sm btn-outline-primary js-person-edit-membership" data-membership-id="${r.id}"><i class="bi bi-pencil"></i> Editar vínculo</button><button type="button" class="btn btn-sm btn-outline-danger js-person-delete-membership" data-membership-id="${r.id}" data-unit="${escapeHtml(r.property_name||'unidad')}"><i class="bi bi-unlink"></i> Desvincular</button></div></div>`).join(''):'<div class="text-body-secondary small">Esta persona todavía no tiene unidades vinculadas.</div>';}});const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const membership=document.getElementById('membershipModal');membership.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;let d={};if(b&&b.classList.contains('js-edit-membership')){try{d=JSON.parse(b.dataset.json||'{}')}catch(x){d={}}}document.getElementById('membershipTitle').textContent=d.id?'Editar vinculación':'Vincular persona a unidad';const map={membershipId:'id',membershipPerson:'person_id',membershipProperty:'property_id',membershipRelation:'relationship_type',membershipAccessProfile:'access_profile_id',membershipStatus:'status',membershipEnds:'ends_at'};for(const [el,k] of Object.entries(map)){let v=d[k]??'';if(el==='membershipEnds'&&v)v=String(v).replace(' ','T').slice(0,16);document.getElementById(el).value=v||(el==='membershipRelation'?'resident':el==='membershipStatus'?'active':'');}if(b&&b.classList.contains('js-link-person'))document.getElementById('membershipPerson').value=b.dataset.person||'';for(const [el,k] of Object.entries({membershipPrimary:'is_primary',membershipInvite:'can_invite',membershipReserve:'can_reserve'})){const x=document.getElementById(el);if(x)x.checked=!!Number(d[k]||0);}});const openMembership=(row={})=>{bootstrap.Modal.getInstance(person)?.hide();setTimeout(()=>{document.getElementById('membershipTitle').textContent=row.id?'Editar vinculación':'Vincular persona a unidad';const map={membershipId:'id',membershipPerson:'person_id',membershipProperty:'property_id',membershipRelation:'relationship_type',membershipAccessProfile:'access_profile_id',membershipStatus:'status',membershipEnds:'ends_at'};for(const [el,k] of Object.entries(map)){let v=row[k]??'';if(el==='membershipEnds'&&v)v=String(v).replace(' ','T').slice(0,16);document.getElementById(el).value=v||(el==='membershipRelation'?'resident':el==='membershipStatus'?'active':'');}for(const [el,k] of Object.entries({membershipPrimary:'is_primary',membershipInvite:'can_invite',membershipReserve:'can_reserve'})){const x=document.getElementById(el);if(x)x.checked=!!Number(row[k]||0);}bootstrap.Modal.getOrCreateInstance(membership).show();},180);};document.getElementById('personAddMembership')?.addEventListener('click',()=>{const pid=Number(document.getElementById('personId').value||0);openMembership({person_id:pid});});document.addEventListener('click',ev=>{const edit=ev.target.closest('.js-person-edit-membership');if(edit){const id=Number(edit.dataset.membershipId||0);const pid=Number(document.getElementById('personId').value||0);const row=(personMemberships[pid]||[]).find(x=>Number(x.id)===id);if(row)openMembership(row);return;}const del=ev.target.closest('.js-person-delete-membership');if(del){const unit=del.dataset.unit||'esta unidad';if(!confirm(`¿Desvincular a esta persona de ${unit}? Los permisos específicos de esa relación también se eliminarán.`))return;document.getElementById('personMembershipDeleteId').value=del.dataset.membershipId||'';document.getElementById('personMembershipDeleteForm').submit();}});});
</script>
<script>
document.addEventListener('DOMContentLoaded',()=>{
  document.getElementById('peopleSelectAll')?.addEventListener('change',e=>document.querySelectorAll('.js-person-select').forEach(x=>x.checked=e.target.checked));
  document.getElementById('membershipsSelectAll')?.addEventListener('change',e=>document.querySelectorAll('.js-membership-select').forEach(x=>x.checked=e.target.checked));
  const personModal=document.getElementById('personModal'),reclassBtn=document.getElementById('personReclassButton'),reclassModal=document.getElementById('personToVehicleModal');
  personModal?.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;let d={};if(b?.classList.contains('js-edit-person')){try{d=JSON.parse(b.dataset.json||'{}')}catch(_){}}reclassBtn?.classList.toggle('d-none',!d.id);});
  reclassBtn?.addEventListener('click',()=>{
    const pid=Number(document.getElementById('personId')?.value||0);if(!pid)return;
    const z=zkPersonMap[pid]||{},rows=(personMemberships[pid]||[]).filter(r=>(r.status||'active')==='active');
    const prop=document.getElementById('reclassProperty');prop.innerHTML=rows.length?rows.map(r=>`<option value="${String(r.property_id).replace(/"/g,'&quot;')}">${String(r.property_name||r.property_code||'Unidad').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}</option>`).join(''):'<option value="">Sin unidad activa: no se puede convertir automáticamente</option>';
    document.getElementById('reclassPersonId').value=pid;document.getElementById('reclassPersonName').textContent=document.getElementById('personDisplay')?.value||'';document.getElementById('reclassDisplay').value=document.getElementById('personDisplay')?.value||`${document.getElementById('personFirst')?.value||''} ${document.getElementById('personLast')?.value||''}`.trim();
    document.getElementById('reclassPlate').value=z.zk_car_plate||'';document.getElementById('reclassRfid').value=z.zk_card_no||'';document.getElementById('reclassMake').value=z.zk_first_name||'';document.getElementById('reclassModel').value=z.zk_last_name||'';document.getElementById('reclassZkLevels').value=z.zk_access_level_ids||'';document.getElementById('reclassColor').value='';document.getElementById('reclassConfirmation').value='';
    bootstrap.Modal.getInstance(personModal)?.hide();setTimeout(()=>bootstrap.Modal.getOrCreateInstance(reclassModal).show(),180);
  });
});
</script><?php endif;?>
